<template>
	<view class="mysignup">
		<view class="activity-detail">
			<view class="meta-card" v-for="item in list" :key="item.activityId"
				@click="to(`/pages/index/activityDetail?id=${item.activityId}`)">
				<text class="title">{{item.activityTitle}}</text>
				<view class="meta-item">
					<text class="meta-icon iconfont icon-wode2"></text>
					<view class="meta-text">
						<text class="meta-label">报名人员姓名</text>
						<text class="meta-value">{{item.contactName}}</text>
					</view>
				</view>
				<view class="meta-item">
					<text class="meta-icon iconfont icon-shouji4"></text>
					<view class="meta-text">
						<text class="meta-label">报名人员姓名手机</text>
						<text class="meta-value">{{item.contactPhone}}</text>
					</view>
				</view>
			</view>

		</view>
		<!-- 		加载提示 -->
		<view class="loading" v-if="showLoading">
			<text style="--i:1">加</text>
			<text style="--i:2">载</text>
			<text style="--i:3">中</text>
			<text style="--i:4">.</text>
			<text style="--i:5">.</text>
			<text style="--i:6">.</text>
		</view>
		<view class="end" v-if="showNone">暂无更多...</view>

	</view>
</template>
<script>
	import {
		loaded,
		loading,
		toast,
		redirectTo,
		navigateTo
	} from '@/utils/index.js';
	import {
		img_PATH,
		LocalStorage
	} from '@/config';
	import {
		queryMyRegistrations
	} from '@/api/index.js'

	export default {
		data() {
			return {
				imgurl: img_PATH,
				CustomBar: this.CustomBar,
				showLoading: false,
				showNone: false,
				accMaskBool: false,
				page: 1,
				limit: 20,
				id: 1,
				item: {},
				list: [],
				info: {
					coverImg: '',
					title: '',
					price: '',
					desc: '',
					startTime: '',
					endTime: '',
					location: '',
					isPaid: 0,
					enrolledCount: '',
					activityStateName: '',
					userRegistered: false, // 当前用户是否已报名
				}
			};
		},
		computed: {

		},
		components: {},
		onLoad(options) {

		},
		mounted() {

		},
		created() {
			this.init()
		},
		// 触底的事件
		onReachBottom() {

		},
		methods: {

			async init() {
				this.showNone = false
				this.showLoading = true
				let _data = await queryMyRegistrations(1, this.page, this.limit);
				if (_data.code == 200) {
					if (_data.data.length === 0) {
						this.showLoading = false
						this.showNone = true
						return
					}
					this.page++
					this.showLoading = false
					this.list = [...this.list, ..._data.data]
				}
			},

			to(path) {
				navigateTo(path)
			},
		},

	}
</script>

<style scoped lang="scss">
	.mysignup {
		min-height: 100vh;
		width: 100%;
		padding: 30rpx 25rpx;
		background-color: #f7f7f7;

		/* 顶部Banner */
		.banner-img {
			width: 100%;
			height: auto;
			display: block;
			border-radius: 15rpx;
		}

		/* 信息卡片 */
		.info-card {
			padding: 32rpx;
			background: #fff;
			border-radius: 16rpx;
			position: relative;
			box-shadow: 0 4rpx 20rpx rgba(0, 0, 0, 0.06);
			margin-top: 20rpx;
		}

		.title {
			font-size: 36rpx;
			font-weight: 700;
			color: #1a1a1a;
			line-height: 1.4;
			display: block;
			margin-bottom: 16rpx;
		}

		.price-row {
			display: flex;
			align-items: baseline;
			gap: 12rpx;
			margin-bottom: 24rpx;
		}

		.price-label {
			font-size: 26rpx;
			color: #999;
		}

		.price-value {
			font-size: 40rpx;
			font-weight: 700;
			color: #ff4d4f;
		}

		.section-title {
			font-size: 30rpx;
			font-weight: 600;
			color: #333;
			margin-bottom: 12rpx;
			display: block;
		}

		.desc-content {
			font-size: 28rpx;
			color: #666;
			line-height: 1.8;
		}

		/* 时间地点卡片 */
		.meta-card {
			margin-bottom: 20rpx;
			padding: 28rpx 32rpx;
			background: #fff;
			border-radius: 16rpx;
			box-shadow: 0 4rpx 20rpx rgba(0, 0, 0, 0.06);
		}

		.meta-item {
			display: flex;
			align-items: flex-start;
			gap: 16rpx;
			padding: 16rpx 0;

			&:not(:last-child) {
				border-bottom: 1rpx solid #f0f0f0;
			}
		}

		.meta-icon {
			font-size: 38rpx;
			flex-shrink: 0;
			color: #333333;
		}

		.meta-text {
			display: flex;
			flex-direction: column;
			gap: 4rpx;
		}

		.meta-label {
			font-size: 30rpx;
			font-weight: bold;
			color: #333;
		}

		.meta-value {
			font-size: 28rpx;
			color: #666666;
			padding-top: 12rpx;
		}

		/* 底部报名栏 */
		.bottom-bar {
			position: fixed;
			left: 0;
			right: 0;
			bottom: 0;
			display: flex;
			align-items: center;
			justify-content: space-between;
			padding: 16rpx 32rpx;
			background: #fff;
			box-shadow: 0 -2rpx 12rpx rgba(0, 0, 0, 0.06);
			z-index: 2;
		}

		.status-info {
			display: flex;
			flex-direction: column;
			gap: 4rpx;
		}

		.status-tag {
			font-size: 28rpx;
			font-weight: 600;

			&.status-open {
				color: #52c41a;
			}

			&.status-signed {
				color: #ff3d3d;
			}

			&.status-full,
			&.status-ended {
				color: #999;
			}
		}

		.remain-count {
			font-size: 22rpx;
			color: #999;
		}

		.signup-btn {
			min-width: 260rpx;
			height: 80rpx;
			line-height: 80rpx;
			border-radius: 40rpx;
			font-size: 30rpx;
			font-weight: 600;
			color: #fff;
			background: linear-gradient(135deg, #ff6b35, #ff4d4f);
			border: none;
			text-align: center;

			&.bgc {
				background: linear-gradient(135deg, #c0c5bc, #a1a39f);
				color: #666666;
			}
		}

		.bottom-placeholder {
			height: calc(120rpx + env(safe-area-inset-bottom));
		}

	}
</style>